function.arguments:
{"command":"python3 << 'EOF'
import wave, numpy as np
w=wave.open('/tmp/plE5b.wav','rb'); sr=w.getframerate()
d=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).astype(float).reshape(-1,2).mean(1)
# find note onsets via energy
env=np.sqrt(np.convolve(d**2,np.ones(500)/500,'same'))
thr=env.max()*0.3
on=[]
for i in range(1,len(env)):
    if env[i]>thr and env[i-1]<=thr: on.append(i/sr)
print("onsets:",[round(x,3) for x in on[:8]])
def pitch(t):
    seg=d[int((t+0.01)*sr):int((t+0.20)*sr)]
    seg=seg-seg.mean()
    ac=np.correlate(seg,seg,'full')[len(seg)-1:]
    l0=int(sr/3000); l1=int(sr/50)
    l=l0+np.argmax(ac[l0:l1])
    return round(sr/l,1)
for t in on[:6]: print(t, pitch(t))
EOF"}

