import json, os

def nn(name):
    p=1 if len(name)>1 and name[1]=='#' else 0
    base={'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
    b=base[name[0].upper()+('#' if p else '')]
    octv=int(name[1+p:])
    return octv*12+b+1  # XM number

KICK,SNARE,HAT,OHAT,BASS,PLUCK,PAD,ARP,CHIP,FX=range(1,11)
CK,CS,CH,CB,CL,CP,CA,CC=range(8)

# chords in XM note numbers via names (A minor: Am F C G)
CHORDS=[
    [nn('A3'),nn('C4'),nn('E4')],   # Am
    [nn('F3'),nn('A3'),nn('C4')],   # F
    [nn('C3'),nn('G3'),nn('B3')],   # Cmaj7
    [nn('G3'),nn('B3'),nn('D4')],   # G
]
BASSLINE=[nn('A2'),nn('F2'),nn('C3'),nn('G2')]

def arpseq(chord,style):
    c=chord+[chord[0]+12]
    if style==0:seq=[0,1,2,3,2,1]*2+[0,1,2,3]
    elif style==1:seq=[0,2,1,3,0,2,1,3,0,2,1,3,0,2,3,2]
    elif style==2:seq=[0,1,2,3]*4
    else:seq=[0,3,2,1]*4
    return [c[i] for i in seq]

def mel_a():
    return [(0,'E5',64),(4,'G5',56),(8,'A5',64),(12,'G5',50),(16,'E5',60),(24,'D5',54),(28,'E5',50),
        (32,'C5',64),(36,'E5',56),(40,'F5',64),(44,'E5',50),(48,'D5',60),(56,'C5',54),(60,'D5',50),
        (64,'E5',64),(68,'G5',56),(72,'A5',64),(76,'G5',50),(80,'E5',60),(88,'D5',54),(92,'E5',50),
        (96,'D5',64),(100,'E5',56),(104,'D5',60),(108,'B4',52),(112,'G4',56),(120,'B4',54),(124,'D5',50)]
def mel_b():
    return [(0,'E5',64),(4,'G5',56),(8,'A5',64),(12,'C6',56),(16,'B5',60),(24,'G5',54),(28,'A5',52),
        (32,'A5',64),(36,'G5',56),(40,'F5',60),(44,'E5',54),(48,'D5',56),(56,'E5',54),(60,'F5',50),
        (64,'G5',64),(68,'A5',56),(72,'C6',64),(76,'B5',52),(80,'G5',60),(88,'A5',54),(92,'B5',50),
        (96,'B5',62),(100,'A5',54),(104,'G5',58),(108,'E5',52),(112,'D5',56),(120,'G5',56),(124,'B5',60)]

cells=[]
def add(pat,row,ch,note=None,inst=0,vol=0,fx=0,fxp=0):
    a={"pattern":pat,"row":row,"channel":ch,"instrument":inst,"volume":vol,"effect":fx,"effect_param":fxp}
    if note is not None:a["note"]=note
    cells.append({"name":"pattern_set_cell","arguments":a})

def bass_pat(pat,ci):
    root=BASSLINE[ci]
    hits=[0,6,8,14,16,22,24,30]
    for i,r in enumerate(hits):
        nt=root+(12 if i in(5,7) else 0)
        add(pat,r,CB,note=nt,inst=BASS,vol=64)
def drum_pat(pat,kicks,snares,hrows,hvols,ohat=None):
    for r in kicks:add(pat,r,CK,note='C-4',inst=KICK,vol=64)
    for r in snares:add(pat,r,CS,note='C-4',inst=SNARE,vol=60)
    for r,v in zip(hrows,hvols):add(pat,r,CH,note='C-4',inst=HAT,vol=v)
    if ohat:
        for r in ohat:add(pat,r,CH,note='C-4',inst=OHAT,vol=54)
def pad_pat(pat,ci,vol=30,rel=False):
    for nt in CHORDS[ci]:add(pat,0,CP,note=nt,inst=PAD,vol=vol)
    if rel:add(pat,28,CP,note=97)
def arp_pat(pat,ci,style,vol=40):
    seq=arpseq(CHORDS[ci],style)
    for i,nt in enumerate(seq):add(pat,i*2,CA,note=nt+12,inst=ARP,vol=vol if i%2==0 else vol-10)
def chip_acc(pat,rn,vol=38):
    for r,ntn in rn:add(pat,r,CC,note=nn(ntn),inst=CHIP,vol=vol)

NP=14
for p in range(NP):
    cells.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":32}})

hA=list(range(0,32,4));hAv=[50,30,40,30]*2
hB=list(range(0,32,2));hBv=[50,26,36,26]*4
hC=list(range(0,32,2));hCv=[52,28,38,30,52,28,38,34]*2

# P0 intro Am
pad_pat(0,0,30)
seq=arpseq(CHORDS[0],2)[8:]
for i,nt in enumerate(seq):add(0,16+i*2,CA,note=nt+12,inst=ARP,vol=34)
add(0,28,CH,note='C-4',inst=OHAT,vol=40)
# P1 intro F
pad_pat(1,1,32);arp_pat(1,1,2,38);drum_pat(1,[],[],hA,hAv)
# P2-P5 section A (Am F C G)
pad_pat(2,0,30);bass_pat(2,0);drum_pat(2,[0,16],[8,24],hB,hBv);arp_pat(2,0,0,40)
pad_pat(3,1,30);bass_pat(3,1);drum_pat(3,[0,16],[8,24],hB,hBv,ohat=[28]);arp_pat(3,1,0,40)
for r,ntn,vl in mel_a():
    if 32<=r<64:add(3,r-32,CL,note=nn(ntn),inst=PLUCK,vol=vl)
pad_pat(4,2,30);bass_pat(4,2);drum_pat(4,[0,16],[8,24],hB,hBv);arp_pat(4,2,0,40)
for r,ntn,vl in mel_a():
    if 64<=r<96:add(4,r-64,CL,note=nn(ntn),inst=PLUCK,vol=vl)
pad_pat(5,3,30,rel=True);bass_pat(5,3);drum_pat(5,[0,16],[8,24],hB,hBv,ohat=[20]);arp_pat(5,3,1,42)
for r,ntn,vl in mel_a():
    if 96<=r<128:add(5,r-96,CL,note=nn(ntn),inst=PLUCK,vol=vl)
chip_acc(5,[(24,'G5'),(28,'D5')])
# P6-P9 section B
for pi,ci in [(6,0),(7,1),(8,2),(9,3)]:
    pad_pat(pi,ci,32,rel=(ci==3));bass_pat(pi,ci)
    drum_pat(pi,[0,10,16],[8,24,31] if pi==6 else [8,24],hC,hCv,
             ohat={6:None,7:[28],8:None,9:[20,26]}[pi])
    arp_pat(pi,ci,{0:2,1:2,2:2,3:3}[ci],44)
for pi,lo in [(6,0),(7,32),(8,64),(9,96)]:
    for r,ntn,vl in mel_b():
        if lo<=r<lo+32:add(pi,r-lo,CL,note=nn(ntn),inst=PLUCK,vol=vl)
chip_acc(9,[(16,'B5'),(20,'G5'),(24,'D6'),(28,'B5')],40)
add(9,30,CC,note=nn('G6'),inst=CHIP,vol=38)
# P10-P11 breakdown
pad_pat(10,0,34);bass_pat(10,0);drum_pat(10,[],[24],hA,hAv,ohat=[16]);arp_pat(10,0,1,42)
for r,ntn,vl in mel_a():
    if 0<=r<32:add(10,r,CL,note=nn(ntn),inst=PLUCK,vol=max(30,vl-8))
pad_pat(11,1,34);bass_pat(11,1);drum_pat(11,[],[8,16,24,28,30,31],hA,hAv);arp_pat(11,1,1,42)
chip_acc(11,[(24,'E5'),(26,'F5'),(28,'G5'),(30,'A5')])
add(11,24,CH,note='C-4',inst=FX,vol=44)
