def nn(name):
    p=1 if len(name)>1 and name[1]=='#' else 0
    base={'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
    b=base[name[0].upper()+('#' if p else '')]
    return int(name[1+p:])*12+b+1

